--------------------------------------------------------------------------------
-- 01_dimensiones.sql
-- DWH OEFA · Oracle BD_CURSOR
-- Creación de las 8 tablas de dimensiones del modelo (ver PROPUESTA_ADAPTADA_ETL.md, sec. 3.2)
--
-- Orden de ejecución: EJECUTAR PRIMERO (los hechos referencian a estas tablas por FK).
-- Motor objetivo: Oracle 12c+ (usa GENERATED BY DEFAULT ON NULL AS IDENTITY, disponible
-- desde 12c). Si el BD_CURSOR corre en una versión anterior, reemplazar la identidad por
-- una SEQUENCE + TRIGGER equivalente.
--
-- Convención: cada dimensión trae sembrado un miembro "NO ESPECIFICADO" con clave -1,
-- para que ningún hecho se pierda por falta de dimensión (ver sección 3.2 de la propuesta).
--------------------------------------------------------------------------------

--------------------------------------------------------------------------------
-- DW_M_DIM_TIEMPO
-- Clave inteligente AAAAMMDD. Se puebla con un script de generación de calendario
-- (fuera del alcance de este DDL); aquí solo se crea la estructura y el miembro ND.
--------------------------------------------------------------------------------
CREATE TABLE DW_M_DIM_TIEMPO (
    ID_TIEMPO             NUMBER(8)      NOT NULL,   -- AAAAMMDD; -1 = NO ESPECIFICADO
    FECHA                 DATE,
    ANIO                  NUMBER(4),
    MES                   NUMBER(2),
    NOMBRE_MES             VARCHAR2(15),
    TRIMESTRE             NUMBER(1),
    SEMANA_ANIO           NUMBER(2),
    DIA                   NUMBER(2),
    DIA_SEMANA            VARCHAR2(10),
    NOMBRE_DIA            VARCHAR2(15),
    ES_FIN_DE_SEMANA      NUMBER(1)      DEFAULT 0,
    ES_FERIADO            NUMBER(1)      DEFAULT 0,
    ES_DIA_HABIL          NUMBER(1)      DEFAULT 1,
    DESCRIPCION_FERIADO   VARCHAR2(200),
    CONSTRAINT PK_DW_M_DIM_TIEMPO PRIMARY KEY (ID_TIEMPO),
    CONSTRAINT CK_DW_M_DIM_TIEMPO_FDS CHECK (ES_FIN_DE_SEMANA IN (0,1)),
    CONSTRAINT CK_DW_M_DIM_TIEMPO_FER CHECK (ES_FERIADO IN (0,1)),
    CONSTRAINT CK_DW_M_DIM_TIEMPO_HAB CHECK (ES_DIA_HABIL IN (0,1))
);

CREATE UNIQUE INDEX UQ_DW_M_DIM_TIEMPO_FECHA ON DW_M_DIM_TIEMPO (FECHA);

-- Miembro NO ESPECIFICADO
INSERT INTO DW_M_DIM_TIEMPO (ID_TIEMPO, FECHA, ANIO, MES, NOMBRE_MES, TRIMESTRE,
                         SEMANA_ANIO, DIA, DIA_SEMANA, NOMBRE_DIA,
                         ES_FIN_DE_SEMANA, ES_FERIADO, ES_DIA_HABIL, DESCRIPCION_FERIADO)
VALUES (-1, NULL, NULL, NULL, 'NO ESPECIFICADO', NULL,
        NULL, NULL, 'NO ESPECIFICADO', 'NO ESPECIFICADO',
        0, 0, 0, NULL);

--------------------------------------------------------------------------------
-- DW_M_DIM_ADMINISTRADO
-- Sin SCD Tipo 2: última versión vigente, actualizada por UPDATE simple.
--------------------------------------------------------------------------------
CREATE TABLE DW_M_DIM_ADMINISTRADO (
    ID_ADMINISTRADO       NUMBER         GENERATED BY DEFAULT ON NULL AS IDENTITY
                                          (START WITH 1 INCREMENT BY 1),
    COD_ADMINISTRADO      VARCHAR2(50)   NOT NULL,   -- ADM##### (SISUD) o NOM-<razón social>
    RAZON_SOCIAL          VARCHAR2(300),
    RAZON_SOCIAL_NORM     VARCHAR2(300),
    RUC                   VARCHAR2(20),
    FECHA_ACTUALIZACION   DATE           DEFAULT SYSDATE,
    CONSTRAINT PK_DW_M_DIM_ADMINISTRADO PRIMARY KEY (ID_ADMINISTRADO),
    CONSTRAINT UQ_DW_M_DIM_ADMINISTRADO_COD UNIQUE (COD_ADMINISTRADO)
);

INSERT INTO DW_M_DIM_ADMINISTRADO (ID_ADMINISTRADO, COD_ADMINISTRADO, RAZON_SOCIAL,
                               RAZON_SOCIAL_NORM, RUC)
VALUES (-1, 'ND', 'NO ESPECIFICADO', 'NO ESPECIFICADO', NULL);

--------------------------------------------------------------------------------
-- DW_M_DIM_ORGANO_UNIDAD
-- Oficinas/coordinaciones/direcciones (ej. DSIS-CRES, DSEM-CMIN, ODES-MOQ, OD-LAM).
--------------------------------------------------------------------------------
CREATE TABLE DW_M_DIM_ORGANO_UNIDAD (
    ID_ORGANO             NUMBER         GENERATED BY DEFAULT ON NULL AS IDENTITY
                                          (START WITH 1 INCREMENT BY 1),
    SIGLA                 VARCHAR2(30)   NOT NULL,
    NOMBRE                VARCHAR2(200),
    DESCRIPCION           VARCHAR2(200),  -- nombre largo CSEP (ej. Minería); catálogo f2_csep_sheets.json
    TIPO                  VARCHAR2(30),   -- DIRECCION / COORDINACION / ODES / OD
    ORGANO_SUPERIOR       VARCHAR2(30),
    FECHA_ACTUALIZACION   DATE           DEFAULT SYSDATE,
    CONSTRAINT PK_DW_M_DIM_ORGANO_UNIDAD PRIMARY KEY (ID_ORGANO),
    CONSTRAINT UQ_DW_M_DIM_ORGANO_SIGLA UNIQUE (SIGLA),
    CONSTRAINT CK_DW_M_DIM_ORGANO_TIPO CHECK (TIPO IN
        ('DIRECCION','COORDINACION','ODES','OD','NO ESPECIFICADO'))
);

INSERT INTO DW_M_DIM_ORGANO_UNIDAD (ID_ORGANO, SIGLA, NOMBRE, DESCRIPCION, TIPO, ORGANO_SUPERIOR)
VALUES (-1, 'ND', 'NO ESPECIFICADO', 'NO ESPECIFICADO', 'NO ESPECIFICADO', NULL);

--------------------------------------------------------------------------------
-- DW_M_DIM_OD
-- Territorio / oficina desconcentrada del Excel F1 (familia medidas administrativas).
-- Distinto de DW_M_DIM_ORGANO_UNIDAD (órgano operativo COORD/expediente).
--------------------------------------------------------------------------------
CREATE TABLE DW_M_DIM_OD (
    ID_OD                 NUMBER         GENERATED BY DEFAULT ON NULL AS IDENTITY
                                          (START WITH 1 INCREMENT BY 1),
    COD_OD                VARCHAR2(30)   NOT NULL,
    NOMBRE                VARCHAR2(100)  NOT NULL,
    TIPO                  VARCHAR2(20)   NOT NULL,  -- OD / ODES / UNIDAD / NO ESPECIFICADO
    ORDEN                 NUMBER(3),
    FECHA_ACTUALIZACION   DATE           DEFAULT SYSDATE,
    CONSTRAINT PK_DW_M_DIM_OD PRIMARY KEY (ID_OD),
    CONSTRAINT UQ_DW_M_DIM_OD_COD UNIQUE (COD_OD),
    CONSTRAINT CK_DW_M_DIM_OD_TIPO CHECK (TIPO IN ('OD','ODES','UNIDAD','NO ESPECIFICADO'))
);

INSERT INTO DW_M_DIM_OD (ID_OD, COD_OD, NOMBRE, TIPO, ORDEN)
VALUES (-1, 'ND', 'NO ESPECIFICADO', 'NO ESPECIFICADO', NULL);

--------------------------------------------------------------------------------
-- DW_M_DIM_FUENTE_REGISTRO
-- Universo de origen de cada fila del hecho (antes dimensión degenerada VARCHAR).
-- CODIGO alinea a FUENTE_REGISTRO / constantes.py; FAMILIA_TDR = F1|F2|F4|F5.
--------------------------------------------------------------------------------
CREATE TABLE DW_M_DIM_FUENTE_REGISTRO (
    ID_FUENTE             NUMBER         GENERATED BY DEFAULT ON NULL AS IDENTITY
                                          (START WITH 1 INCREMENT BY 1),
    CODIGO                VARCHAR2(20)   NOT NULL,   -- OD_SHEETS / CAGR / GAPPS / SISUD_VW
    NOMBRE                VARCHAR2(100)  NOT NULL,
    FAMILIA_TDR           VARCHAR2(10),              -- F1 / F2 / F4 / F5 / ND
    DESCRIPCION           VARCHAR2(300),
    FECHA_ACTUALIZACION   DATE           DEFAULT SYSDATE,
    CONSTRAINT PK_DW_M_DIM_FUENTE PRIMARY KEY (ID_FUENTE),
    CONSTRAINT UQ_DW_M_DIM_FUENTE_COD UNIQUE (CODIGO)
);

INSERT INTO DW_M_DIM_FUENTE_REGISTRO (ID_FUENTE, CODIGO, NOMBRE, FAMILIA_TDR, DESCRIPCION)
VALUES (-1, 'ND', 'NO ESPECIFICADO', 'ND', 'NO ESPECIFICADO');
