--------------------------------------------------------------------------------
-- DW_M_DIM_PARAMETRO_UIT
-- Base de la regla de calidad R05 (MONTO_S = MULTA_UIT × UIT(año)). Sembrada con
-- valores oficiales del MEF; el año en curso se actualiza al publicarse el Decreto
-- Supremo correspondiente (ver hallazgo H6 en la propuesta).
--------------------------------------------------------------------------------
CREATE TABLE DW_M_DIM_PARAMETRO_UIT (
    ID_UIT                NUMBER         GENERATED BY DEFAULT ON NULL AS IDENTITY
                                          (START WITH 1 INCREMENT BY 1),
    ANIO                  NUMBER(4)      NOT NULL,
    VALOR_UIT             NUMBER(12,2)   NOT NULL,
    FECHA_ACTUALIZACION   DATE           DEFAULT SYSDATE,
    CONSTRAINT PK_DW_M_DIM_PARAMETRO_UIT PRIMARY KEY (ID_UIT),
    CONSTRAINT UQ_DW_M_DIM_PARAMETRO_UIT_ANIO UNIQUE (ANIO),
    CONSTRAINT CK_DW_M_DIM_PARAMETRO_UIT_VALOR CHECK (VALOR_UIT > 0)
);

